async function registerTools(){const mc=document.modelContext;if(!mc?.registerTool)return;try{await mc.registerTool({name:'get_longform_project',description:'Read sentence IDs, scripts, audio durations and scene review status from the current longform editing project.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({name:project.name,sentences:project.sentences.map(s=>({id:s.id,text:s.text,durationSeconds:duration(s),scene:s.scene}))})});await mc.registerTool({name:'update_longform_scenes',description:'Apply validated page descriptions to existing sentence IDs. Resets review status. Does not record audio, generate assets or export a video.',inputSchema:{type:'object',properties:{scenes:{type:'array',items:{type:'object',properties:{id:{type:'integer'},title:{type:'string'},subtitle:{type:'string'},layout:{type:'string',enum:['title','split','full']},motion:{type:'string',enum:['fade','zoom','slide','none']},background:{type:'string'},captions:{type:'boolean'}},required:['id'],additionalProperties:false}}},required:['scenes'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(busy||recording)throw Error('Editor is busy');if(!Array.isArray(input?.scenes))throw Error('scenes array required');const checked=input.scenes.map(validScene),seen=new Set();for(const v of checked){if(seen.has(v.id)||!project.sentences.some(s=>s.id===v.id))throw Error('Unknown or duplicate sentence ID');seen.add(v.id);if(v.asset&&!project.assets[v.asset])throw Error('Asset not loaded');}stopPlayback();for(const v of checked){const s=project.sentences.find(s=>s.id===v.id);s.scene={...s.scene,...v,reviewed:false};}scheduleSave();render();return{updated:checked.map(s=>s.id)};}});}catch(e){console.info('Optional agent tools unavailable',e);}}
async function importAudioFiles(files){
 if(busy||recording||!files.length)return;setBusy(true);stopPlayback();
 try{let entries=[],script=[];
 for(const file of files){if(/\.zip$/i.test(file.name)){const contents=readZip(new Uint8Array(await file.arrayBuffer()));const manifest=contents['manifest.json']||contents['project.json'];if(manifest){const m=JSON.parse(strFromU8(manifest));if(Array.isArray(m.sentences))script=m.sentences;}for(const[name,data]of Object.entries(contents))if(/\.(wav|mp3|m4a|aac|ogg|webm|flac|mp4)$/i.test(name))entries.push(new File([data],name));}else if(file.type.startsWith('audio/')||/\.(wav|mp3|m4a|aac|ogg|webm|flac|mp4)$/i.test(file.name))entries.push(file);else throw Error('지원하지 않는 음성 파일: '+file.name);}
 if(!entries.length)throw Error('가져올 음성 파일이 없습니다.');
 const plan=planAudioImports(entries,project.sentences,current()?.id,script);
 if(plan.some(p=>project.sentences.find(s=>s.id===p.id)?.audio)&&!confirm('같은 번호의 기존 녹음을 가져온 파일로 교체할까요?'))return;
 const decoded=[];for(let i=0;i<plan.length;i++){toast(`음성 가져오는 중 ${i+1} / ${plan.length}`);decoded.push({...plan[i],audio:await decodeAudio(plan[i].file)});}
 if(!project.sentences.length){project.sentences=decoded.map(p=>newSentence(p.text,p.id)).sort((a,b)=>a.id-b.id);selected=0;}
 for(const p of decoded){const s=project.sentences.find(s=>s.id===p.id);if(s.audio)undo.set(s.id,s.audio);s.audio=p.audio;s.scene.reviewed=false;}
 changed();render();toast(decoded.length+'개 음성을 문장에 연결했습니다.');
 }catch(e){toast('음성 가져오기 실패: '+e.message);}finally{setBusy(false);}
}
